def first_address_is_default(apps, schema_editor):
    SavedAddress = apps.get_model("users", "SavedAddress")
    seen = set()
    for address in SavedAddress.objects.order_by("user_id", "id"):
        if address.user_id not in seen:
            seen.add(address.user_id)
            address.is_default = True
            address.save(update_fields=["is_default"])


def managers_see_customers(apps, schema_editor):
    GroupInfo = apps.get_model("users", "GroupInfo")
    for info in GroupInfo.objects.filter(group__name="Managers"):
        info.perms = list(info.perms or []) + [c for c in ("admin.customers.view", "admin.customers.edit", "admin.customers.delete")
                                              if c not in (info.perms or [])]
        info.save(update_fields=["perms"])


